async def _ensure_school_columns(engine):
    async with engine.begin() as conn:
        def missing_columns(sync_conn):
            columns = {column["name"] for column in inspect(sync_conn).get_columns("schools")}
            return [name for name in NEW_SCHOOL_COLUMNS if name not in columns]

        for column_name in await conn.run_sync(missing_columns):
            await conn.execute(text(f"ALTER TABLE schools ADD COLUMN {column_name} {NEW_SCHOOL_COLUMNS[column_name]}"))


async def _ensure_review_columns(engine):
    async with engine.begin() as conn:
        def missing_columns(sync_conn):
            columns = {column["name"] for column in inspect(sync_conn).get_columns("reviews")}
            return [name for name in NEW_REVIEW_COLUMNS if name not in columns]

        for column_name in await conn.run_sync(missing_columns):
            await conn.execute(text(f"ALTER TABLE reviews ADD COLUMN {column_name} {NEW_REVIEW_COLUMNS[column_name]}"))


async def _upsert_schools(session: AsyncSession):
    for item in SEED:
        school = (await session.execute(select(School).where(School.name == item["name"]))).scalar_one_or_none()
        if school is None:
            school = School(**item)
            session.add(school)
            continue
        for key, value in item.items():
            setattr(school, key, value)
    await session.commit()


async def _upsert_teachers(session: AsyncSession):
    schools = {row.name: row.id for row in (await session.execute(select(School))).scalars().all()}
    for school_name, name, subject, description, rating, review_summary, source_url in TEACHERS:
        school_id = schools.get(school_name)
        if not school_id:
            continue
        teacher = (await session.execute(select(Teacher).where(Teacher.school_id == school_id, Teacher.name == name, Teacher.subject == subject))).scalar_one_or_none()
        values = dict(school_id=school_id, name=name, subject=subject, description=description, rating=rating,
                      review_summary=review_summary, social_url=TEACHER_SOCIALS.get((school_name, name), ""),
                      source_url=source_url, evidence_type="официальный профиль/отзывы/соцсеть")
        if teacher is None:
            session.add(Teacher(**values))
        else:
            for key, value in values.items():
                setattr(teacher, key, value)
    await session.commit()


async def _remove_obsolete_teacher_rows(session: AsyncSession):
    """Remove records left by corrected research, so a wrong legacy card is not shown."""
    school_id = (await session.execute(select(School.id).where(School.name == "99 Баллов"))).scalar_one_or_none()
    if school_id:
        await session.execute(
            text("DELETE FROM teachers WHERE school_id = :school_id AND name = :name AND subject = :subject"),
            {"school_id": school_id, "name": "Ляйсан Хайбуллина", "subject": "Информатика"},
        )
        await session.commit()


async def init_db(url: str):
    engine = create_async_engine(url)
    async with engine.begin() as conn:
        await conn.run_sync(Base.metadata.create_all)
    await _ensure_school_columns(engine)
    await _ensure_review_columns(engine)
    session_factory = async_sessionmaker(engine, expire_on_commit=False)
    async with session_factory() as session:
        await _upsert_schools(session)
        await _upsert_teachers(session)
        await _remove_obsolete_teacher_rows(session)
    return engine, session_factory


async def get_or_create_user(session: AsyncSession, telegram_id: int) -> User:
    user = (await session.execute(select(User).where(User.telegram_id == telegram_id))).scalar_one_or_none()
    if not user:
        user = User(telegram_id=telegram_id)
        session.add(user)
        await session.commit()
    return user
